import{Lt as e,Z as t,_t as n,vt as r}from"./chunks/framework.CsLlEPF4.js";var i=JSON.parse(`{"title":"Plugin Store Now Available in English","description":"","frontmatter":{"title":"Plugin Store Now Available in English","date":"2026-3-7","draft":false,"authors":["Northword"]},"headers":[],"relativePath":"blog/posts/english-version-for-plugin-market.md","filePath":"blog/blog-repo/posts/english-version-for-plugin-market.md"}`),a={name:`blog/posts/english-version-for-plugin-market.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /blog/posts/english-version-for-plugin-market.md for this page in Markdown format</div><h1 id="the-plugin-store-is-now-available-in-english" tabindex="-1">The Plugin Store is Now Available in English <a class="header-anchor" href="#the-plugin-store-is-now-available-in-english" aria-label="Permalink to “The Plugin Store is Now Available in English”">​</a></h1><p>Hi everyone,</p><p>We are thrilled to see that the Zotero Plugin Store, maintained by our Chinese community, has become a valuable resource for so many users—including many from non-Chinese speaking regions.</p><p>Since the official Zotero plugin gallery is still under development, we wanted to bridge the gap and make it easier for international users to discover and download plugins. To that end, we have officially launched an <strong>English version</strong> of the Plugin Store.</p><p><strong>Key Details:</strong></p><ul><li><strong>Scope:</strong> Scope &amp; Availability: Currently, English support is limited to the <strong>store’s homepage</strong> and <strong>core index pages</strong>.<br> Please be aware that since we have not finished translating the entire site, accessing untranslated pages may result in a 404 error.</li><li><strong>Language Switcher:</strong> You can manually toggle between languages using the <strong>&quot;文/A&quot;</strong> icon located in the top-right corner of the page.</li><li><strong>Auto-Detection:</strong> The site will now automatically detect your browser’s language settings and suggest the appropriate version.</li></ul><hr><p>In Chinese</p><p>Zotero 插件商店英文版正式上线</p><p>大家好！</p><p>很高兴看到由中文社区维护的「Zotero 插件商店」为众多同学提供了便利。我们注意到，除了中文用户，许多来自非中文母语国家的同学也在使用我们的服务。</p><p>鉴于 Zotero 官方插件商店仍处于开发阶段，为了在过渡期间更好地帮助全球用户发现和下载插件，我们正式推出了<strong>插件商店的英文版本</strong>。</p><p><strong>说明：</strong></p><ul><li>目前仅<strong>插件商店主页</strong>及相关<strong>索引页</strong>提供英文支持，其他页面暂无多语言计划。请注意：由于我们尚未完成全站翻译，访问部分未翻译页面可能会显示 404 错误。</li><li><strong>语言切换：</strong> 您可以点击页面右上角的 <strong>「文/A」</strong> 图标手动切换。</li><li><strong>自动识别：</strong> 网站现在支持检测浏览器语言，并会根据您的设置引导至相应的语言页面。</li></ul>`,15)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};